THOUGHT: I now need to compute, from the per-issue results table, the reproduction rates for Roam, ReCDroid, and Yakusu over all reports, reports without missing steps, and reports with missing steps, using the “Reproduction Result” columns and the “# Missing Steps” column.

<mini_swe_agent_bash>
awk -F'|' '
$2 ~ /^[0-9]+$/ {
  total_all++;
  ms = $7 + 0;

  rr_roam = $9; gsub(/^[ \t]+|[ \t]+$/, "", rr_roam); rr_roam = tolower(rr_roam);
  rr_recd = $24; gsub(/^[ \t]+|[ \t]+$/, "", rr_recd); rr_recd = tolower(rr_recd);
  rr_yaku = $56; gsub(/^[ \t]+|[ \t]+$/, "", rr_yaku); rr_yaku = tolower(rr_yaku);

  if (rr_roam == "success") roam_all++;
  if (rr_recd == "success") recd_all++;
  if (rr_yaku == "success") yaku_all++;

  if (ms == 0) {
    total_nomiss++;
    if (rr_roam == "success") roam_nomiss++;
    if (rr_recd == "success") recd_nomiss++;
    if (rr_yaku == "success") yaku_nomiss++;
  } else {
    total_miss++;
    if (rr_roam == "success") roam_miss++;
    if (rr_recd == "success") recd_miss++;
    if (rr_yaku == "success") yaku_miss++;
  }
}
END {
  printf "Totals: all=%d, no-missing=%d, missing=%d\n", total_all, total_nomiss, total_miss;
  printf "Roam: all=%.4f no-missing=%.4f missing=%.4f\n", 100*roam_all/total_all, 100*roam_nomiss/total_nomiss, 100*roam_miss/total_miss;
  printf "ReCDroid: all=%.4f no-missing=%.4f missing=%.4f\n", 100*recd_all/total_all, 100*recd_nomiss/total_nomiss, 100*recd_miss/total_miss;
  printf "Yakusu: all=%.4f no-missing=%.4f missing=%.4f\n", 100*yaku_all/total_all, 100*yaku_nomiss/total_nomiss, 100*yaku_miss/total_miss;
}' ROAM-Artifact/ROAM-Artifact/Evaluation/results.md
</mini_swe_agent_bash>

