uvx --from pymupdf4llm python -c 'import sys, pymupdf4llm as p; sys.stdout.write(p.to_markdown(sys.argv[1]))' ROAM-Artifact/ROAM-Artifact/Evaluation/results.pdf > ROAM-Artifact/ROAM-Artifact/Evaluation/results.md

awk -F'|' '
$2 ~ /^[0-9]+$/ {
  total_all++;
  ms = $7 + 0;

  rr_roam = $9;  gsub(/^[ \t]+|[ \t]+$/, "", rr_roam);  rr_roam = tolower(rr_roam);
  rr_recd = $24; gsub(/^[ \t]+|[ \t]+$/, "", rr_recd); rr_recd = tolower(rr_recd);
  rr_yaku = $56; gsub(/^[ \t]+|[ \t]+$/, "", rr_yaku); rr_yaku = tolower(rr_yaku);

  if (rr_roam == "success") roam_all++;
  if (rr_recd == "success") recd_all++;
  if (rr_yaku == "success") yaku_all++;

  if (ms == 0) {
    total_nomiss++;
    if (rr_roam == "success") roam_nomiss++;
    if (rr_recd == "success") recd_nomiss++;
    if (rr_yaku == "success") yaku_nomiss++;
  } else {
    total_miss++;
    if (rr_roam == "success") roam_miss++;
    if (rr_recd == "success") recd_miss++;
    if (rr_yaku == "success") yaku_miss++;
  }
}
END {
  roam_all_p     = 100 * roam_all     / total_all;
  roam_nomiss_p  = 100 * roam_nomiss  / total_nomiss;
  roam_miss_p    = 100 * roam_miss    / total_miss;

  recd_all_p     = 100 * recd_all     / total_all;
  recd_nomiss_p  = 100 * recd_nomiss  / total_nomiss;
  recd_miss_p    = 100 * recd_miss    / total_miss;

  yaku_all_p     = 100 * yaku_all     / total_all;
  yaku_nomiss_p  = 100 * yaku_nomiss  / total_nomiss;
  yaku_miss_p    = 100 * yaku_miss    / total_miss;

  printf "**Table 3: Reproduction Rate of Each Approach (Shown as a Percent)**\n\n";
  printf "|          | All Reports | Reports w/o Missing Steps | Reports w/ Missing Steps |\n";
  printf "| -------- | :---------: | :-----------------------: | :----------------------: |\n";
  printf "| ReCDroid | %11.1f | %23.1f | %22.1f |\n", recd_all_p, recd_nomiss_p, recd_miss_p;
  printf "| Yakusu   | %11.1f | %23.1f | %22.1f |\n", yaku_all_p, yaku_nomiss_p, yaku_miss_p;
  printf "| Roam     | %11.1f | %23.1f | %22.1f |\n", roam_all_p, roam_nomiss_p, roam_miss_p;
}' ROAM-Artifact/ROAM-Artifact/Evaluation/results.md > /workspace/repro.txt

# Section 4: Formatting and submission block
echo '<artisan_submit>'
cat /workspace/repro.txt
echo '</artisan_submit>'
EOF
chmod +x /workspace/repro_roam_table_3.sh
artisan submit /workspace/repro_roam_table_3.sh
</mini_swe_agent_bash>

