  rr_roam = $9;  gsub(/^[ \t]+|[ \t]+$/, "", rr_roam);  rr_roam = tolower(rr_roam);
  if (rr_roam == "success") {
    roam_succ_all++;
    if (ms == 0) roam_succ_nomiss++; else roam_succ_miss++;
  }

  # ReCDroid (only if cell non-empty)
  rr_recd = $24; gsub(/^[ \t]+|[ \t]+$/, "", rr_recd); rr_recd = tolower(rr_recd);
  if (rr_recd != "") {
    recd_tot_all++;
    if (ms == 0) recd_tot_nomiss++; else recd_tot_miss++;
    if (rr_recd == "success") {
      recd_succ_all++;
      if (ms == 0) recd_succ_nomiss++; else recd_succ_miss++;
    }
  }

  # Yakusu (only if cell non-empty)
  rr_yaku = $56; gsub(/^[ \t]+|[ \t]+$/, "", rr_yaku); rr_yaku = tolower(rr_yaku);
  if (rr_yaku != "") {
    yaku_tot_all++;
    if (ms == 0) yaku_tot_nomiss++; else yaku_tot_miss++;
    if (rr_yaku == "success") {
      yaku_succ_all++;
      if (ms == 0) yaku_succ_nomiss++; else yaku_succ_miss++;
    }
