  printf "Roam totals: all=%d no-miss=%d miss=%d succ_all=%d succ_no=%d succ_miss=%d\n", roam_tot_all, roam_tot_nomiss, roam_tot_miss, roam_succ_all, roam_succ_nomiss, roam_succ_miss;
