  printf "Roam rates: all=%.4f no-miss=%.4f miss=%.4f\n",
         100*roam_succ_all/roam_tot_all, 100*roam_succ_nomiss/roam_tot_nomiss, 100*roam_succ_miss/roam_tot_miss;

  printf "ReCDroid rates: all=%.4f no-miss=%.4f miss=%.4f\n",
         100*recd_succ_all/recd_tot_all, 100*recd_succ_nomiss/recd_tot_nomiss, 100*recd_succ_miss/recd_tot_miss;

  printf "Yakusu rates: all=%.4f no-miss=%.4f miss=%.4f\n",
         100*yaku_succ_all/yaku_tot_all, 100*yaku_succ_nomiss/yaku_tot_nomiss, 100*yaku_succ_miss/yaku_tot_miss;
